class Solution {
public:
    int findClosestLeaf(TreeNode* root, int k) {
        unordered_map<int, vector<int>> graph;
        unordered_set<int> leaves;

        function<void(TreeNode*)> dfs = [&](TreeNode* node) {
            if (!node) return;
            if (!node->left && !node->right) leaves.insert(node->val);
            if (node->left) {
                graph[node->val].push_back(node->left->val);
                graph[node->left->val].push_back(node->val);
                dfs(node->left);
            }
            if (node->right) {
                graph[node->val].push_back(node->right->val);
                graph[node->right->val].push_back(node->val);
                dfs(node->right);
            }
        };
        dfs(root);

        queue<int> q;
        unordered_set<int> visited = {k};
        q.push(k);

        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            if (leaves.count(curr)) return curr;
            for (int nxt : graph[curr]) {
                if (!visited.count(nxt)) {
                    visited.insert(nxt);
                    q.push(nxt);
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int findClosestLeaf(TreeNode root, int k) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        Set<Integer> leaves = new HashSet<>();
        buildGraph(root, graph, leaves);

        Queue<Integer> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();
        queue.offer(k);
        visited.add(k);

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            if (leaves.contains(curr)) return curr;
            for (int nxt : graph.getOrDefault(curr, Collections.emptyList())) {
                if (!visited.contains(nxt)) {
                    visited.add(nxt);
                    queue.offer(nxt);
                }
            }
        }
        return -1;
    }

    private void buildGraph(TreeNode node, Map<Integer, List<Integer>> graph, Set<Integer> leaves) {
        if (node == null) return;
        graph.putIfAbsent(node.val, new ArrayList<>());
        if (node.left == null && node.right == null) leaves.add(node.val);
        if (node.left != null) {
            graph.putIfAbsent(node.left.val, new ArrayList<>());
            graph.get(node.val).add(node.left.val);
            graph.get(node.left.val).add(node.val);
            buildGraph(node.left, graph, leaves);
        }
        if (node.right != null) {
            graph.putIfAbsent(node.right.val, new ArrayList<>());
            graph.get(node.val).add(node.right.val);
            graph.get(node.right.val).add(node.val);
            buildGraph(node.right, graph, leaves);
        }
    }
}

